   105→// CondenseSession condenses a session's shadow branch to permanent storage.
   106→// checkpointID is the 12-hex-char value from the Entire-Checkpoint trailer.
   107→// Metadata is stored at sharded path: <checkpoint_id[:2]>/<checkpoint_id[2:]>/
   108→// Uses checkpoint.GitStore.WriteCommitted for the git operations.
   109→func (s *ManualCommitStrategy) CondenseSession(repo *git.Repository, checkpointID id.CheckpointID, state *SessionState) (*CondenseResult, error) {
   110→	// Get shadow branch
   111→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
   112→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
   113→	ref, err := repo.Reference(refName, true)
   114→	if err != nil {
   115→		return nil, fmt.Errorf("shadow branch not found: %w", err)
   116→	}
   117→
   118→	// Extract session data from the shadow branch (with live transcript fallback).
   119→	// Use tracked files from session state instead of collecting all files from tree.
   120→	// Pass agent type to handle different transcript formats (JSONL for Claude, JSON for Gemini).
   121→	// Pass live transcript path so condensation reads the current file rather than a
   122→	// potentially stale shadow branch copy (SaveChanges may have been skipped if the
   123→	// last turn had no code changes).
   124→	// Pass CheckpointTranscriptStart for accurate token calculation (line offset for Claude, message index for Gemini).
   125→	sessionData, err := s.extractSessionData(repo, ref.Hash(), state.SessionID, state.FilesTouched, state.AgentType, state.TranscriptPath, state.CheckpointTranscriptStart)
   126→	if err != nil {
   127→		return nil, fmt.Errorf("failed to extract session data: %w", err)
   128→	}
   129→
   130→	// Get checkpoint store
   131→	store, err := s.getCheckpointStore()
   132→	if err != nil {
   133→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
   134→	}
   135→
   136→	// Get author info
   137→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
   138→	attribution := calculateSessionAttributions(repo, ref, sessionData, state)
   139→	// Get current branch name
   140→	branchName := GetCurrentBranchName(repo)
   141→
   142→	// Generate summary if enabled
   143→	var summary *cpkg.Summary
   144→	if settings.IsSummarizeEnabled() && len(sessionData.Transcript) > 0 {
   145→		logCtx := logging.WithComponent(context.Background(), "attribution")
   146→		summarizeCtx := logging.WithComponent(logCtx, "summarize")
   147→
   148→		// Scope transcript to this checkpoint's portion
   149→		scopedTranscript := transcript.SliceFromLine(sessionData.Transcript, state.CheckpointTranscriptStart)
   150→		if len(scopedTranscript) > 0 {
   151→			var err error
   152→			summary, err = summarize.GenerateFromTranscript(summarizeCtx, scopedTranscript, sessionData.FilesTouched, nil)
   153→			if err != nil {
   154→				logging.Warn(summarizeCtx, "summary generation failed",
   155→					slog.String("session_id", state.SessionID),
   156→					slog.String("error", err.Error()))
   157→				// Continue without summary - non-blocking
   158→			} else {
   159→				logging.Info(summarizeCtx, "summary generated",
   160→					slog.String("session_id", state.SessionID))
   161→			}
   162→		}
   163→	}
   164→
   165→	// Write checkpoint metadata using the checkpoint store
   166→	if err := store.WriteCommitted(context.Background(), cpkg.WriteCommittedOptions{
   167→		CheckpointID:                checkpointID,
   168→		SessionID:                   state.SessionID,
   169→		Strategy:                    StrategyNameManualCommit,
   170→		Branch:                      branchName,
   171→		Transcript:                  sessionData.Transcript,
   172→		Prompts:                     sessionData.Prompts,
   173→		Context:                     sessionData.Context,
   174→		FilesTouched:                sessionData.FilesTouched,
   175→		CheckpointsCount:            state.StepCount,
   176→		EphemeralBranch:             shadowBranchName,
   177→		AuthorName:                  authorName,
   178→		AuthorEmail:                 authorEmail,
   179→		Agent:                       state.AgentType,
   180→		TranscriptIdentifierAtStart: state.TranscriptIdentifierAtStart,
   181→		CheckpointTranscriptStart:   state.CheckpointTranscriptStart,
   182→		TokenUsage:                  sessionData.TokenUsage,
   183→		InitialAttribution:          attribution,
   184→		Summary:                     summary,
   185→	}); err != nil {
   186→		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
   187→	}
   188→
