   190→		CheckpointID:         checkpointID,
   191→		SessionID:            state.SessionID,
   192→		CheckpointsCount:     state.StepCount,
   193→		FilesTouched:         sessionData.FilesTouched,
   194→		TotalTranscriptLines: sessionData.FullTranscriptLines,
