   198→func calculateSessionAttributions(repo *git.Repository, shadowRef *plumbing.Reference, sessionData *ExtractedSessionData, state *SessionState) *cpkg.InitialAttribution {
   199→	// Calculate initial attribution using accumulated prompt attribution data.
   200→	// This uses user edits captured at each prompt start (before agent works),
   201→	// plus any user edits after the final checkpoint (shadow → head).
   202→	logCtx := logging.WithComponent(context.Background(), "attribution")
   203→	var attribution *cpkg.InitialAttribution
   204→	headRef, headErr := repo.Head()
   205→	if headErr != nil {
   206→		logging.Debug(logCtx, "attribution skipped: failed to get HEAD",
   207→			slog.String("error", headErr.Error()))
   208→	} else {
   209→		headCommit, commitErr := repo.CommitObject(headRef.Hash())
   210→		if commitErr != nil {
   211→			logging.Debug(logCtx, "attribution skipped: failed to get HEAD commit",
   212→				slog.String("error", commitErr.Error()))
   213→		} else {
   214→			headTree, treeErr := headCommit.Tree()
   215→			if treeErr != nil {
   216→				logging.Debug(logCtx, "attribution skipped: failed to get HEAD tree",
   217→					slog.String("error", treeErr.Error()))
   218→			} else {
   219→				// Get shadow branch tree (checkpoint tree - what the agent wrote)
   220→				shadowCommit, shadowErr := repo.CommitObject(shadowRef.Hash())
   221→				if shadowErr != nil {
   222→					logging.Debug(logCtx, "attribution skipped: failed to get shadow commit",
   223→						slog.String("error", shadowErr.Error()),
   224→						slog.String("shadow_ref", shadowRef.Hash().String()))
   225→				} else {
   226→					shadowTree, shadowTreeErr := shadowCommit.Tree()
   227→					if shadowTreeErr != nil {
   228→						logging.Debug(logCtx, "attribution skipped: failed to get shadow tree",
   229→							slog.String("error", shadowTreeErr.Error()))
   230→					} else {
   231→						// Get base tree (state before session started)
   232→						var baseTree *object.Tree
   233→						if baseCommit, baseErr := repo.CommitObject(plumbing.NewHash(state.BaseCommit)); baseErr == nil {
   234→							if tree, baseTErr := baseCommit.Tree(); baseTErr == nil {
   235→								baseTree = tree
   236→							} else {
   237→								logging.Debug(logCtx, "attribution: base tree unavailable",
   238→									slog.String("error", baseTErr.Error()))
   239→							}
   240→						} else {
   241→							logging.Debug(logCtx, "attribution: base commit unavailable",
   242→								slog.String("error", baseErr.Error()),
   243→								slog.String("base_commit", state.BaseCommit))
   244→						}
   245→
   246→						// Log accumulated prompt attributions for debugging
   247→						var totalUserAdded, totalUserRemoved int
   248→						for i, pa := range state.PromptAttributions {
   249→							totalUserAdded += pa.UserLinesAdded
   250→							totalUserRemoved += pa.UserLinesRemoved
   251→							logging.Debug(logCtx, "prompt attribution data",
   252→								slog.Int("checkpoint", pa.CheckpointNumber),
   253→								slog.Int("user_added", pa.UserLinesAdded),
   254→								slog.Int("user_removed", pa.UserLinesRemoved),
   255→								slog.Int("agent_added", pa.AgentLinesAdded),
   256→								slog.Int("agent_removed", pa.AgentLinesRemoved),
   257→								slog.Int("index", i))
   258→						}
   259→
   260→						attribution = CalculateAttributionWithAccumulated(
   261→							baseTree,
   262→							shadowTree,
   263→							headTree,
   264→							sessionData.FilesTouched,
   265→							state.PromptAttributions,
   266→						)
   267→
   268→						if attribution != nil {
   269→							logging.Info(logCtx, "attribution calculated",
   270→								slog.Int("agent_lines", attribution.AgentLines),
   271→								slog.Int("human_added", attribution.HumanAdded),
   272→								slog.Int("human_modified", attribution.HumanModified),
   273→								slog.Int("human_removed", attribution.HumanRemoved),
   274→								slog.Int("total_committed", attribution.TotalCommitted),
   275→								slog.Float64("agent_percentage", attribution.AgentPercentage),
   276→								slog.Int("accumulated_user_added", totalUserAdded),
   277→								slog.Int("accumulated_user_removed", totalUserRemoved),
   278→								slog.Int("files_touched", len(sessionData.FilesTouched)))
   279→						}
   280→					}
   281→				}
   282→			}
   283→		}
   284→	}
   285→	return attribution
   286→}
