   288→// extractSessionData extracts session data from the shadow branch.
   289→// filesTouched is the list of files tracked during the session (from SessionState.FilesTouched).
   290→// agentType identifies the agent (e.g., "Gemini CLI", "Claude Code") to determine transcript format.
   291→// liveTranscriptPath, when non-empty and readable, is preferred over the shadow branch copy.
   292→// This handles the case where SaveChanges was skipped (no code changes) but the transcript
   293→// continued growing — the shadow branch copy would be stale.
   294→// checkpointTranscriptStart is the line offset (Claude) or message index (Gemini) where the current checkpoint began.
   295→func (s *ManualCommitStrategy) extractSessionData(repo *git.Repository, shadowRef plumbing.Hash, sessionID string, filesTouched []string, agentType agent.AgentType, liveTranscriptPath string, checkpointTranscriptStart int) (*ExtractedSessionData, error) {
   296→	commit, err := repo.CommitObject(shadowRef)
   297→	if err != nil {
   298→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   299→	}
   300→
   301→	tree, err := commit.Tree()
   302→	if err != nil {
   303→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   304→	}
   305→
   306→	data := &ExtractedSessionData{}
   307→	// sessionID is already an "entire session ID" (with date prefix)
   308→	metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
   309→
   310→	// Extract transcript — prefer the live file when available, fall back to shadow branch.
   311→	// The shadow branch copy may be stale if the last turn ended without code changes
   312→	// (SaveChanges is only called when there are file modifications).
   313→	var fullTranscript string
   314→	if liveTranscriptPath != "" {
   315→		if liveData, readErr := os.ReadFile(liveTranscriptPath); readErr == nil && len(liveData) > 0 { //nolint:gosec // path from session state
   316→			fullTranscript = string(liveData)
   317→		}
   318→	}
   319→	if fullTranscript == "" {
   320→		// Fall back to shadow branch copy
   321→		if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
   322→			if content, contentErr := file.Contents(); contentErr == nil {
   323→				fullTranscript = content
   324→			}
   325→		} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
   326→			if content, contentErr := file.Contents(); contentErr == nil {
   327→				fullTranscript = content
   328→			}
   329→		}
   330→	}
   331→
   332→	// Process transcript based on agent type
   333→	if fullTranscript != "" {
   334→		data.Transcript = []byte(fullTranscript)
   335→		data.FullTranscriptLines = countTranscriptItems(agentType, fullTranscript)
   336→		data.Prompts = extractUserPrompts(agentType, fullTranscript)
   337→		data.Context = generateContextFromPrompts(data.Prompts)
   338→	}
   339→
   340→	// Use tracked files from session state (not all files in tree)
   341→	data.FilesTouched = filesTouched
   342→
   343→	// Calculate token usage from the extracted transcript portion
   344→	if len(data.Transcript) > 0 {
   345→		data.TokenUsage = calculateTokenUsage(agentType, data.Transcript, checkpointTranscriptStart)
   346→	}
   347→
   348→	return data, nil
   349→}
   350→
   351→// countTranscriptItems counts lines (JSONL) or messages (JSON) in a transcript.
   352→// For Claude Code and JSONL-based agents, this counts lines.
   353→// For Gemini CLI and JSON-based agents, this counts messages.
   354→// Returns 0 if the content is empty or malformed.
   355→func countTranscriptItems(agentType agent.AgentType, content string) int {
   356→	if content == "" {
   357→		return 0
   358→	}
   359→
   360→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
   361→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
   362→		transcript, err := geminicli.ParseTranscript([]byte(content))
   363→		if err == nil && transcript != nil && len(transcript.Messages) > 0 {
   364→			return len(transcript.Messages)
   365→		}
   366→		// If agentType is explicitly Gemini but parsing failed, return 0
   367→		if agentType == agent.AgentTypeGemini {
   368→			return 0
   369→		}
   370→		// Otherwise fall through to JSONL parsing for Unknown type
   371→	}
   372→
   373→	// Claude Code and other JSONL-based agents
   374→	allLines := strings.Split(content, "\n")
   375→	// Trim trailing empty lines (from final \n in JSONL)
   376→	for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
   377→		allLines = allLines[:len(allLines)-1]
   378→	}
   379→	return len(allLines)
   380→}
