   382→// extractUserPrompts extracts all user prompts from transcript content.
   383→// Returns prompts with IDE context tags stripped (e.g., <ide_opened_file>).
   384→func extractUserPrompts(agentType agent.AgentType, content string) []string {
   385→	if content == "" {
   386→		return nil
   387→	}
   388→
   389→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
   390→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
   391→		prompts, err := geminicli.ExtractAllUserPrompts([]byte(content))
   392→		if err == nil && len(prompts) > 0 {
   393→			// Strip IDE context tags for consistency with Claude Code handling
   394→			cleaned := make([]string, 0, len(prompts))
   395→			for _, prompt := range prompts {
   396→				if stripped := textutil.StripIDEContextTags(prompt); stripped != "" {
   397→					cleaned = append(cleaned, stripped)
   398→				}
   399→			}
   400→			return cleaned
   401→		}
   402→		// If agentType is explicitly Gemini but parsing failed, return nil
   403→		if agentType == agent.AgentTypeGemini {
   404→			return nil
   405→		}
   406→		// Otherwise fall through to JSONL parsing for Unknown type
   407→	}
   408→
   409→	// Claude Code and other JSONL-based agents
   410→	return extractUserPromptsFromLines(strings.Split(content, "\n"))
   411→}
