   413→// calculateTokenUsage calculates token usage from raw transcript data.
   414→// startOffset is the line number (Claude Code) or message index (Gemini CLI)
   415→// where the current checkpoint began, allowing calculation for only the portion
   416→// of the transcript since the last checkpoint.
   417→func calculateTokenUsage(agentType agent.AgentType, data []byte, startOffset int) *agent.TokenUsage {
   418→	if len(data) == 0 {
   419→		return &agent.TokenUsage{}
   420→	}
   421→
   422→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
   423→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
   424→		// Attempt to parse as Gemini JSON
   425→		transcript, err := geminicli.ParseTranscript(data)
   426→		if err == nil && transcript != nil && len(transcript.Messages) > 0 {
   427→			return geminicli.CalculateTokenUsage(data, startOffset)
   428→		}
   429→		// If agentType is explicitly Gemini but parsing failed, return empty usage
   430→		if agentType == agent.AgentTypeGemini {
   431→			return &agent.TokenUsage{}
   432→		}
   433→		// Otherwise fall through to JSONL parsing for Unknown type
   434→	}
   435→
   436→	// Claude Code and other JSONL-based agents
   437→	lines, err := claudecode.ParseTranscript(data)
   438→	if err != nil || len(lines) == 0 {
   439→		return &agent.TokenUsage{}
   440→	}
   441→	// Slice transcript lines to only include checkpoint portion
   442→	if startOffset > 0 && startOffset < len(lines) {
   443→		lines = lines[startOffset:]
   444→	}
   445→	return claudecode.CalculateTokenUsage(lines)
   446→}
